-- Read-only business manifest of everything the reset empties (run on prod right before confirmation/execution).
select jsonb_pretty(jsonb_build_object(
 'pos_penjualan', (select jsonb_build_object('struk',count(*),'total',coalesce(sum(total),0),'dari',min(created_at),'sampai',max(created_at)) from public.sales),
 'pos_retur', (select jsonb_build_object('n',count(*),'total',coalesce(sum(total),0)) from public.sales_returns),
 'klinik_invoice', (select jsonb_build_object('n',count(*),'aktif',count(*) filter (where voided_at is null),'total_aktif',coalesce(sum(total) filter (where voided_at is null),0),
     'per_status',(select jsonb_object_agg(coalesce(paid_status,'-'),n) from (select paid_status,count(*) n from public.invoices where voided_at is null group by 1) x)) from public.invoices),
 'klinik_pembayaran', (select jsonb_build_object('n',count(*),'total',coalesce(sum(amount),0)) from public.invoice_payments),
 'klinik_kwitansi', (select jsonb_build_object('n',count(*),'total',coalesce(sum(total),0)) from public.clinic_payment_receipts),
 'klinik_dp', (select jsonb_build_object('n',count(*),'diterima',coalesce(sum(amount),0),'terpakai',coalesce(sum(applied),0),'sisa',coalesce(sum(amount-applied),0)) from public.clinic_customer_advances),
 'klinik_kunjungan_terbuka_dengan_tagihan_atau_dp', (select jsonb_agg(jsonb_build_object('visit',v.id,'status',v.status,'cabang',b.name,
     'invoice_aktif',(select count(*) from public.invoices i where i.visit_id=v.id and i.voided_at is null),
     'dp_sisa',(select coalesce(sum(amount-applied),0) from public.clinic_customer_advances a where a.visit_id=v.id),
     'rawat_inap_aktif',exists(select 1 from public.inpatient_records r where r.visit_id=v.id and r.discharged_at is null)))
   from public.visits v join public.branches b on b.id=v.branch_id where v.status<>'Selesai'
    and (exists(select 1 from public.invoices i where i.visit_id=v.id) or exists(select 1 from public.clinic_customer_advances a where a.visit_id=v.id))),
 'racikan_sudah_ambil_stok_belum_ditagih', (select count(distinct recipe_id) from public.compound_issues where posted_invoice_item_id is null and restored_at is null),
 'grosir', jsonb_build_object('pesanan',(select count(*) from public.sales_orders),'pengiriman',(select count(*) from public.sales_deliveries),
     'faktur',(select jsonb_build_object('n',count(*),'total',coalesce(sum(total),0)) from public.sales_invoices where opening_batch_id is null),
     'penerimaan',(select jsonb_build_object('n',count(*),'total',coalesce(sum(jumlah),0)) from public.sales_receipts)),
 'pembelian', jsonb_build_object('po',(select jsonb_build_object('n',count(*),'total',coalesce(sum(total),0)) from public.purchase_orders),
     'penerimaan_barang',(select count(*) from public.goods_receipts),
     'faktur',(select jsonb_build_object('n',count(*),'aktif',count(*) filter (where voided_at is null),'total_aktif',coalesce(sum(total) filter (where voided_at is null),0)) from public.purchase_invoices where opening_batch_id is null),
     'pembayaran',(select jsonb_build_object('n',count(*),'total',coalesce(sum(amount) filter (where voided_at is null),0)) from public.purchase_invoice_payments),
     'uang_muka',(select jsonb_build_object('n',count(*),'jumlah',coalesce(sum(jumlah),0),'terpakai',coalesce(sum(terpakai),0)) from public.purchase_advances)),
 'saldo_awal_per_faktur', (select jsonb_agg(jsonb_build_object('as_of',as_of,'utang_n',ap_count,'utang',ap_total,'piutang_n',ar_count,'piutang',ar_total)) from public.opening_invoice_batches),
 'jurnal', (select jsonb_build_object('n',count(distinct e.id),'baris',count(l.id),'debit',coalesce(sum(l.debit),0),'kredit',coalesce(sum(l.credit),0)) from public.journal_entries e left join public.journal_lines l on l.entry_id=e.id),
 'saldo_buku_besar_per_akun', (select jsonb_object_agg(code||' '||name, saldo) from (select c.code,c.name,sum(l.debit-l.credit) saldo from public.journal_lines l join public.coa_accounts c on c.id=l.account_id group by 1,2 having sum(l.debit-l.credit)<>0 order by 1) x),
 'kas_bank_per_rekening', (select jsonb_object_agg(a.nama,coalesce((select sum(l.debit-l.credit) from public.journal_lines l join public.coa_accounts c on c.id=l.account_id where c.code=a.coa_code),0)) from public.cash_accounts a),
 'shift_kasir', (select jsonb_build_object('n',count(*),'terbuka',count(*) filter (where status='open')) from public.cashier_shifts),
 'pengeluaran', (select jsonb_build_object('n',count(*),'total',coalesce(sum(jumlah),0),'lampiran',(select count(*) from public.document_attachments where modul='pengeluaran')) from public.expenses),
 'kas_masuk_keluar', (select count(*) from public.cash_entries),
 'stok', jsonb_build_object('baris_saldo',(select count(*) from public.stock),'qty_total',(select coalesce(sum(qty),0) from public.stock),
     'barang_bersaldo',(select count(distinct item_id) from public.stock where qty<>0),
     'nilai_layer',(select coalesce(round(sum(qty_left*unit_cost),2),0) from public.stock_layers),'layer',(select count(*) from public.stock_layers),'mutasi',(select count(*) from public.stock_moves),
     'stok_awal_accurate_terkunci',(select count(*) from public.stock_layers where source='saldo-awal-accurate')),
 'pemindahan_barang', (select count(*) from public.stock_transfers),
 'permintaan_barang', (select count(*) from public.stock_requests),
 'opname', (select jsonb_build_object('perintah',count(*),'hasil',(select count(*) from public.opname_results),'diposting',(select count(*) from public.opname_posting_receipts)) from public.opname_orders),
 'produksi', (select count(*) from public.production_orders),
 'poin_pelanggan', (select jsonb_build_object('pelanggan',count(*) filter (where points<>0),'poin',coalesce(sum(points),0),'total_belanja',coalesce(sum(total_spending),0),'tier_naik',count(*) filter (where tier<>'New')) from public.customers),
 'komisi_poin_staf', jsonb_build_object('efek_penjualan',(select count(*) from public.sale_staff_effects),'poin_staf',(select coalesce(sum(total_points),0) from public.staff_points),'progres_quest',(select count(*) from public.staff_quest_progress)),
 'aset_tetap_tetap_disimpan', (select jsonb_build_object('n',count(*),'harga_perolehan',coalesce(sum(harga_perolehan),0)) from public.fixed_assets),
 'kasbon_karyawan_tetap_disimpan', (select jsonb_build_object('n',count(*),'jumlah',coalesce(sum(jumlah),0)) from public.cash_advances)
)) report;
